var LEVELS = ["P1","P2","P3","P4","P5","P6","JSS1","JSS2","JSS3"];
var LEVEL_BASE = {"P1":300,"P2":550,"P3":800,"P4":1050,"P5":1300,"P6":1550,"JSS1":1800,"JSS2":2050,"JSS3":2300};
function levelIndex(level) { var i = LEVELS.indexOf(String(level || 'P3')); return i < 0 ? 0 : i; }
var START_BELOW = 2;
var JUMP_UP = 5, JUMP_DOWN = 3;
/**
 * A child is "in" a class when that class's own skills are the ones they get right 3 times in 4: Elo puts that 400·log10(3) ≈ 190
 * above the skill, so 190 above the class's base. Without it a rating on P2's base is asked P1's skills, and a jump changes nothing.
 */
var PLAY_AT = 190;
/** TPL-013 SC-1: a new player is rated START_BELOW classes below the one picked; the class is a first guess. */
function startRating(level) { return classRating(Math.max(0, levelIndex(level) - START_BELOW)); }
/** The rating that puts a child at the start of class i. */
function classRating(i) { return LEVEL_BASE[LEVELS[i]] + PLAY_AT + 50; }
/** The class the race asks from: the highest class whose base the rating has reached. The class picked is only where it began. */
function playIndex(r) { var p = 0; for (var i = 0; i < LEVELS.length; i++) if (r >= LEVEL_BASE[LEVELS[i]] + PLAY_AT) p = i; return p; }
/** A class with nothing to ask in this subject yet borrows the nearest class that has something, below before above. */
function nearestClass(curriculum, wanted, li) {
  for (var d = 1; d < LEVELS.length; d++) {
    var tries = [li - d, li + d];
    for (var t = 0; t < 2; t++) {
      var at = tries[t];
      if (at < 0 || at >= LEVELS.length) continue;
      var got = curriculum.filter(function (sk) { return wanted.indexOf(subjectOf(sk)) !== -1 && !sk.beyond && levelIndex(sk.level) === at; });
      if (got.length) return got;
    }
  }
  return [];
}
function rnd(a, b) { return a + Math.floor(Math.random() * (b - a + 1)); }
function pickOne(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function shuffle(arr) { var a = arr.slice(); for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
function isFr(lang) { return String(lang) === 'fr'; }
/** 1234567.5 → "1 234 567,5" (fr, grouped with a narrow no-break space) or "1,234,567.5" (en). RKT-003: an ordinary space let a phone break "8 266" across two lines. */
function fmtNum(n, lang) {
  var neg = n < 0; n = Math.abs(n);
  var s = String(Math.round(n * 1000) / 1000);
  var parts = s.split('.');
  var int = parts[0]; var out = '';
  while (int.length > 3) { out = (isFr(lang) ? ' ' : ',') + int.slice(-3) + out; int = int.slice(0, -3); }
  out = int + out;
  if (parts[1]) out += (isFr(lang) ? ',' : '.') + parts[1];
  return (neg ? '−' : '') + out;
}
/** What a typed answer becomes before comparison: numbers as numbers, words lower-case. */
function normalise(v) {
  var s = String(v === undefined || v === null ? '' : v).trim().toLowerCase();
  var num = s.replace(/\s+/g, '').replace(/,/g, '.');
  if (/^-?\d+(\.\d+)?$/.test(num)) return String(Number(num));
  var big = s.replace(/[\s.,']/g, '');
  if (/^-?\d+$/.test(big) && /\d[\s.,']\d{3}/.test(s)) return String(Number(big));
  // P113: words. A curly apostrophe is an apostrophe, a hyphen is a space (forty-seven, forty seven), a full stop at the end says nothing.
  return s.replace(/[’ʼ]/g, "'").replace(/-/g, ' ').replace(/\.$/, '').replace(/\s+/g, ' ').trim();
}
function sameAnswer(a, b) { return normalise(a) === normalise(b); }
/** P113 REV-001: the subject a skill is filed under. The maths and typing skills carry none; their strand says. */
function subjectOf(sk) { return sk && sk.subject ? String(sk.subject) : sk && sk.strand === 'typing' ? 'typing' : 'maths'; }

var EN_ONES = ['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
var EN_TENS = ['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
function enUnder1000(n) {
  var out = '';
  if (n >= 100) { out = EN_ONES[Math.floor(n / 100)] + ' hundred'; n = n % 100; if (n > 0) out += ' and '; }
  if (n >= 20) { out += EN_TENS[Math.floor(n / 10)]; if (n % 10) out += '-' + EN_ONES[n % 10]; }
  else if (n > 0 || out === '') out += EN_ONES[n];
  return out;
}
function spellEn(n) {
  n = Math.floor(Number(n)); if (n === 0) return 'zero';
  var blocks = [[1000000000, 'billion'], [1000000, 'million'], [1000, 'thousand']];
  var parts = [];
  for (var i = 0; i < blocks.length; i++) { var q = Math.floor(n / blocks[i][0]); if (q > 0) { parts.push(enUnder1000(q) + ' ' + blocks[i][1]); n = n % blocks[i][0]; } }
  if (n > 0) { if (parts.length && n < 100) parts.push('and ' + enUnder1000(n)); else parts.push(enUnder1000(n)); }
  return parts.join(' ');
}
